  // Return two different indices whose prices add to target, or null.
  return null;
}

console.log(pairIndices([4, 11, 8, 3, 15], 19));

solution:
function pairIndices(prices: number[], target: number): [number, number] | null {
  const seen = new Map<number, number>();
  for (let i = 0; i < prices.length; i++) {
    const j = seen.get(target - prices[i]);
    if (j !== undefined) return [j, i];
    seen.set(prices[i], i);
  }
  return null;
}
